BEGIN;
CREATE TEMP TABLE staging_municipal_boundaries (
  cvegeo varchar(5) PRIMARY KEY,
  name varchar(100) NOT NULL,
  state_name varchar(100) NOT NULL,
  boundary geometry NOT NULL
);


-- Idempotent: replace on cvegeo conflict rather than accumulating duplicates.
SELECT cvegeo, name, state_name, boundary FROM staging_municipal_boundaries
ON CONFLICT (cvegeo) DO UPDATE SET
  name = EXCLUDED.name, state_name = EXCLUDED.state_name, boundary = EXCLUDED.boundary;

SELECT count(*) AS imported_count FROM municipal_boundaries;
COMMIT;